                op!(r, at, 0xCB04F..0xCB052, 5, r.cpu.hst_clear(2)); // SB=0
                op!(r, at, 0xCB052..0xCB055, 5, r.cpu.srb(R::C)); // CSRB
                branch!(r, at, 0xCB05A, 7, r.cpu.hs_test(2, Some(0xCB04D))); // ?SB=0 / GOYES #LOG2.loop1
